import{_ as e}from"./chunks/p-menara-iso.DMwiSOyK.js";import{_ as i}from"./chunks/light-day.DtofRIMi.js";import{_ as n}from"./chunks/cam-drone-f200.CBVLKMmF.js";import{_ as t,o as r,c as o,a0 as l}from"./chunks/framework.B7o6dWmz.js";const y=JSON.parse('{"title":"Workshop Blender: Newbie → Master","description":"","frontmatter":{},"headers":[],"relativePath":"workshop.md","filePath":"workshop.md"}'),d={name:"workshop.md"};function s(m,a,p,u,k,g){return r(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="workshop-blender-newbie-→-master" tabindex="-1">Workshop Blender: Newbie → Master <a class="header-anchor" href="#workshop-blender-newbie-→-master" aria-label="Permalink to &quot;Workshop Blender: Newbie → Master&quot;">​</a></h1><p>Workshop daring <strong>self-paced</strong> untuk mahasiswa D-3 Teknik Informatika JTK POLBAN: mulai dari nol besar (belum pernah membuka Blender) sampai mampu memproduksi <strong>video animasi MP4 + Web 3D interaktif GLB</strong> dari karya sendiri — semuanya lewat 4 modul praktikum yang sudah teruji plus satu proyek akhir (capstone).</p><p>Perjalanan ini dirancang sebagai <strong>pre-kursus mata kuliah Komputer Grafik (25TI3103, Semester III)</strong>: selesaikan sebelum praktikum dimulai, dan kamu datang ke pertemuan pertama sudah membawa portofolio 3D utuh.</p><div class="info custom-block"><p class="custom-block-title">Prasyarat</p><ul><li><strong>Blender 4.3</strong> (4.3.2) — lihat Bagian II tiap modul untuk panduan instalasi &amp; spesifikasi mesin (engine EEVEE Next, ringan untuk laptop kampus).</li><li>Mampu membaca Python dasar (perulangan, fungsi, dictionary) — tidak perlu bisa menulis dari nol.</li><li>Semua berkas (kode &amp; dokumen pendamping) tersedia di halaman <a href="/unduh.html">Unduh Berkas</a>.</li></ul></div><p><strong>Estimasi total: ±32–40 jam</strong> · rekomendasi laju <strong>1 level per minggu (4 minggu) + minggu ke-5 capstone</strong>.</p><h2 id="cara-ikut-workshop" tabindex="-1">Cara Ikut Workshop <a class="header-anchor" href="#cara-ikut-workshop" aria-label="Permalink to &quot;Cara Ikut Workshop&quot;">​</a></h2><ol><li><strong>Unduh berkas</strong> dari halaman <a href="/unduh.html">Unduh Berkas</a> — kode sumber tiap modul atau satu paket <code>kg-workshop.zip</code> (lihat <a href="#dua-jalur-kode-monolith-vs-paket-kg-workshop">Dua Jalur Kode</a>).</li><li><strong>Ikuti level secara berurutan</strong> — Level 1 → 4. Setiap level = satu modul: baca Bagian I (konsep), kerjakan Task I–V di Bagian III.</li><li><strong>Lewati gerbang kelulusan</strong> — tiap level punya ceklis artefak (tangkapan layar, file <code>.blend</code>, laporan singkat). Simpan semuanya di folder portofolio pribadi <code>prak[N]_[NIM]</code>.</li><li><strong>Uji penempatan (opsional)</strong> — merasa sudah paham materi Level 1–2? Jawab uji penempatan di tiap level; yakin semua benar → silakan lanjut.</li><li><strong>Kerjakan Capstone</strong> — <a href="/capstone.html">City Tour Kampus Sendiri</a>. Capstone <strong>wajib</strong> dan menjadi syarat penuntasan workshop.</li><li><strong>Selesai</strong> — portofolio <code>prak[1-4]_[NIM]</code> + <code>capstone_[NIM]</code> diverifikasi oleh dosen pengampu saat praktikum dimulai.</li></ol><h2 id="dua-jalur-kode-monolith-vs-paket-kg-workshop" tabindex="-1">Dua Jalur Kode: Monolith vs Paket kg_workshop <a class="header-anchor" href="#dua-jalur-kode-monolith-vs-paket-kg-workshop" aria-label="Permalink to &quot;Dua Jalur Kode: Monolith vs Paket kg_workshop&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Jalur Monolith</th><th>Jalur Paket <code>kg_workshop</code></th></tr></thead><tbody><tr><td>Berkas</td><td><code>modul2.py</code>, <code>modul3.py</code>, <code>modul4.py</code> (satu berkas per modul)</td><td><code>kg-workshop.zip</code> (satu paket untuk semua)</td></tr><tr><td>Cara pakai</td><td>Buka di Text Editor → <strong>Run Script (Alt + P)</strong></td><td>Install sekali sebagai add-on → panel <strong>KG Workshop</strong> di N-sidebar</td></tr><tr><td>Isi</td><td>Persis kode di Lampiran C tiap modul</td><td>Kelas yang sama, dipecah modular: <code>core/</code>, <code>builders/</code>, <code>anim/</code>, <code>ui/</code></td></tr><tr><td>Cocok untuk</td><td>Mengikuti alur modul apa adanya</td><td>Alur workshop &amp; capstone (komponen bisa dipakai lintas modul tanpa salin-tempel)</td></tr></tbody></table><p>Keduanya menghasilkan scene yang identik — pilih sesuai selera. Jalur modul tetap memakai monolith; capstone memakai paket <code>kg_workshop</code>.</p><p><strong>Instalasi paket <code>kg_workshop</code></strong> (sekali saja):</p><ol><li>Unduh <a href="/kode/kg-workshop.zip" download>kg-workshop.zip</a> dari <a href="/unduh.html">Unduh Berkas</a>.</li><li>Blender → <code>Edit → Preferences → Add-ons → Install…</code> → pilih ZIP → aktifkan <strong>KG Workshop</strong>.</li><li>Buka N-sidebar (tombol <code>N</code>) → tab <strong>KG Workshop</strong> → tombol <em>Jalankan Modul 1–4</em> dan <em>Jalankan Capstone</em> siap dipakai.</li></ol><h2 id="peta-jenjang" tabindex="-1">Peta Jenjang <a class="header-anchor" href="#peta-jenjang" aria-label="Permalink to &quot;Peta Jenjang&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Modul</th><th>Kompetensi Inti</th><th>Gerbang Kelulusan</th><th>Estimasi</th></tr></thead><tbody><tr><td>1</td><td><a href="/modul/modul-01.html">Modul 1</a></td><td>Pipeline ASCII→JSON→3D, pemodelan prosedural, material palet PBR, render F12</td><td>Denah ETS pribadi + 2 furnitur baru + analisis SOLID</td><td>±6–8 jam</td></tr><tr><td>2</td><td><a href="/modul/modul-02.html">Modul 2</a></td><td>Matriks homogen 4×4, hierarki scene graph, tekstur prosedural &amp; UV, panel add-on</td><td><code>prak2_[NIM].blend</code> + panel LegoApp + laporan matriks</td><td>±6 jam</td></tr><tr><td>3</td><td><a href="/modul/modul-03.html">Modul 3</a></td><td>4 jenis cahaya, preset suasana, kota makro ASCII, shading emisif</td><td><code>prak3_[NIM].blend</code> + trio suasana + laporan preset</td><td>±5–6 jam</td></tr><tr><td>4</td><td><a href="/modul/modul-04.html">Modul 4</a></td><td>4 kamera virtual, keyframe, siklus siang-malam, render MP4, ekspor GLB</td><td><code>prak4_[NIM].blend</code> + CityTour.mp4 + GLB viewer</td><td>±7–8 jam</td></tr><tr><td>Capstone</td><td><a href="/capstone.html">Halaman Capstone</a></td><td>Gabungan 1→3→4, karya orisinal end-to-end</td><td><code>capstone_[NIM].blend</code> + <code>.mp4</code> + <code>.glb</code> + laporan</td><td>±4–6 jam</td></tr></tbody></table><h2 id="level-1-·-modul-1-—-denah-2d-ascii-menjadi-3d" tabindex="-1">Level 1 · Modul 1 — Denah 2D ASCII Menjadi 3D <a class="header-anchor" href="#level-1-·-modul-1-—-denah-2d-ascii-menjadi-3d" aria-label="Permalink to &quot;Level 1 · Modul 1 — Denah 2D ASCII Menjadi 3D&quot;">​</a></h2><p><strong>±6–8 jam</strong> · prasyarat: tidak ada (mulai dari nol).</p><p>Mulai dari filosofi <em>config-driven</em>: gambar denah rumah dengan karakter <code>+</code>, <code>-</code>, <code>|</code> dan nama ruangan, lalu skrip <code>ascii_to_blender_3d.py</code> membangun dinding, pintu, jendela, hingga furnitur secara otomatis — lengkap dengan material PBR dan render pratinjau.</p><p><strong>Kompetensi:</strong></p><ul><li>Membaca &amp; memodifikasi konfigurasi <code>DENAH_ASCII</code> dan palet material <code>config_assets.json</code></li><li>Memahami parser (dinding, T-junction, pintu/jendela otomatis) dan arsitektur SOLID-nya</li><li>Membangun furnitur primitif baru melalui <code>AssetBuilder</code> (penerapan OCP)</li><li>Render pratinjau F12 dan tangkapan <code>Numpad 7</code></li></ul><p><strong>Belajar di:</strong> <a href="/modul/modul-01.html#bagian-i-bahan-kajian">Bahan Kajian Modul 1</a> → <a href="/modul/modul-01.html#bagian-iii-prosedur-pelaksanaan-praktikum-step-by-step">Task I–IV</a> → <a href="/modul/modul-01.html#iii-6-tugas-praktikum">Tugas Praktikum</a>.</p><p><strong>Gerbang kelulusan — ceklis portofolio <code>prak1_[NIM]</code>:</strong></p><ul><li>[ ] Denah ETS 2D milik sendiri: tangkapan <em>Top Orthographic</em> (<code>Numpad 7</code>) bersanding dengan teks ASCII-nya</li><li>[ ] Render perspektif hasil denah sendiri (<code>F12</code>, 1280×720)</li><li>[ ] ≥ 2 tipe furnitur primitif baru (masing-masing ≥ 3 primitif) tampil di denah</li><li>[ ] Analisis singkat penerapan SRP, OCP, dan Fail-Fast (1 paragraf per poin)</li></ul><details><summary><b>Uji penempatan Level 1</b> — yakin bisa semua? Jawab tanpa membuka modul.</summary><ol><li>Karakter apa di <code>DENAH_ASCII</code> yang menggambar dinding horizontal dan dinding vertikal?</li><li>Apa fungsi tombol <code>Alt + P</code> di Text Editor Blender?</li><li><code>Numpad 7</code> mengubah viewport menjadi tampak apa?</li><li>Bagaimana format penulisan warna di palet material <code>config_assets.json</code>?</li><li>Apa yang diselesaikan mekanisme <em>T-junction resolution</em> pada parser?</li></ol><details><summary>Kunci jawaban</summary><ol><li><code>-</code> untuk horizontal, <code>|</code> untuk vertikal (persegiannya di <code>+</code>).</li><li>Menjalankan skrip Python yang sedang terbuka (<em>Run Script</em>).</li><li><em>Top Orthographic</em> — tampak atas lurus ke bawah.</li><li>RGBA dengan nilai 0.0–1.0 per kanal, mis. <code>[1.0, 0.8, 0.6, 1.0]</code>.</li><li>Menyambungkan ujung dinding vertikal (<code>|</code>) yang bertemu dinding horizontal (<code>-</code>) agar tidak ada celah/overlap di pertemuan T.</li></ol></details></details><h2 id="level-2-·-modul-2-—-transformasi-hierarki-tekstur" tabindex="-1">Level 2 · Modul 2 — Transformasi, Hierarki &amp; Tekstur <a class="header-anchor" href="#level-2-·-modul-2-—-transformasi-hierarki-tekstur" aria-label="Permalink to &quot;Level 2 · Modul 2 — Transformasi, Hierarki &amp; Tekstur&quot;">​</a></h2><p><strong>±6 jam</strong> · prasyarat: lulus Level 1.</p><p>Di balik setiap gerakan objek ada matematika: matriks transformasi homogen 4×4 (<code>T · Rz · Ry · Rx · Shear · S</code>), hierarki parent-child ala menara LEGO, dan jaringan node tekstur prosedural.</p><p><img src="'+e+'" alt="Menara LEGO hasil hierarki scene graph — Level 2"></p><p><strong>Kompetensi:</strong></p><ul><li>Membaca &amp; meracik komposisi matriks homogen, memahami urutan komposisi dan <em>shearing</em></li><li>Membangun hierarki scene graph: <em>root pivot</em> Empty → anak modular (<code>M_world = M_parent · M_local</code>)</li><li>Membuat material Brick/Checker/Wood/Noise lewat <code>TextureMaterialFactory</code> + UV mapping</li><li>Memakai panel interaktif <strong>LegoApp M2</strong> (spawn brick, apply matrix, apply texture)</li></ul><p><strong>Belajar di:</strong> <a href="/modul/modul-02.html#i-4-konsep-kunci-1-matriks-transformasi-homogen-4×4-transform3dengine">Konsep Matriks Homogen</a> → <a href="/modul/modul-02.html#iii-1-task-i-eksplorasi-sudut-pandang-numpad-view">Task I–V</a> → <a href="/modul/modul-02.html#lampiran-b-cookbook-resep-cepat">Cookbook</a>.</p><p><strong>Gerbang kelulusan — ceklis portofolio <code>prak2_[NIM]</code>:</strong></p><ul><li>[ ] <code>prak2_[NIM].blend</code>: scene hasil <code>modul2.py</code> + minimal 1 balok LEGO hasil panel LegoApp M2</li><li>[ ] Tangkapan <code>Numpad 1</code>, <code>3</code>, <code>7</code> setelah transformasi hierarki diterapkan</li><li>[ ] Tangkapan panel LegoApp M2 terbuka + Outliner hierarki menara</li><li>[ ] Laporan singkat: urutan komposisi matriks yang dipakai + preset tekstur yang dicoba</li></ul><details><summary><b>Uji penempatan Level 2</b></summary><ol><li>Sebutkan urutan komposisi transformasi di <code>Transform3DEngine</code>.</li><li>Bagaimana transformasi parent memengaruhi anaknya di scene graph?</li><li>Apa itu <em>Empty</em> dan kenapa dipakai sebagai <em>root pivot</em> balok LEGO?</li><li>Apa beda tekstur prosedural (mis. Brick/Noise) dengan tekstur gambar (image texture)?</li><li>Interpolasi apa yang membuat gerakan keyframe halus <em>pelan-cepat-pelan</em>? <em>(peletakan pertanyaan menyinggung Level 4 — cukup jawab dari intuisi)</em></li></ol><details><summary>Kunci jawaban</summary><ol><li><code>T · Rz · Ry · Rx · Shear · S</code> — translasi, rotasi tiga sumbu, geser, skala.</li><li>Transformasi parent diwariskan ke seluruh anak: <code>M_world = M_parent · M_local</code>.</li><li>Objek tanpa geometri sebagai poros grup; memutar/menggesernya menggerakkan seluruh anak tanpa mengubah bentuk anak.</li><li>Prosedural dihitung dari node matematis (tanpa berkas gambar, skala tak terbatas); image texture memetakan piksel gambar via UV.</li><li>Interpolasi BEZIER (ease-in-out).</li></ol></details></details><h2 id="level-3-·-modul-3-—-pencahayaan-kota-makro" tabindex="-1">Level 3 · Modul 3 — Pencahayaan &amp; Kota Makro <a class="header-anchor" href="#level-3-·-modul-3-—-pencahayaan-kota-makro" aria-label="Permalink to &quot;Level 3 · Modul 3 — Pencahayaan &amp; Kota Makro&quot;">​</a></h2><p><strong>±5–6 jam</strong> · prasyarat: lulus Level 2.</p><p>Kota muncul dari teks: masterplan ASCII berisi 3 gedung 2 lantai, jalan bermarka, taman, dan PJU — lalu hidup lewat empat jenis cahaya dan tiga preset suasana DAY/SUNSET/NIGHT.</p><p><img src="'+i+'" alt="Kota makro pada preset DAY — Level 3"></p><p><strong>Kompetensi:</strong></p><ul><li>Membedakan SUN (directional), Point, Spot, dan Area light beserta bayangannya</li><li>Memakai preset waktu <code>LightingRigManager</code> &amp; menganimasikan posisi matahari (elevasi → arah &amp; panjang bayangan)</li><li>Membangun kota makro dari <code>PETA_MAKRO_ASCII</code> via panel <strong>MacroLight M3</strong></li><li>Shading emisif untuk suasana malam (PJU, jendela gedung menyala)</li></ul><p><strong>Belajar di:</strong> <a href="/modul/modul-03.html#i-4-konsep-kunci-1-empat-jenis-cahaya-preset-suasana-lightingrigmanager">Konsep Empat Jenis Cahaya</a> → <a href="/modul/modul-03.html#iii-1-task-i-eksplorasi-masterplan-sudut-pandang-numpad">Task I–V</a> → <a href="/modul/modul-03.html#lampiran-b-cookbook-resep-cepat">Cookbook</a>.</p><p><strong>Gerbang kelulusan — ceklis portofolio <code>prak3_[NIM]</code>:</strong></p><ul><li>[ ] <code>prak3_[NIM].blend</code>: kawasan modul3.py + minimal 2 objek tambahan hasil panel (Task V)</li><li>[ ] Tangkapan trio DAY/SUNSET/NIGHT dari sudut sama + 1 malam dari kamera scene</li><li>[ ] Tangkapan kerucut sorot PJU malam + panel MacroLight M3 terbuka</li><li>[ ] Laporan singkat: tabel perbandingan 3 preset + pengaruh elevasi matahari terhadap bayangan</li></ul><details><summary><b>Uji penempatan Level 3</b></summary><ol><li>Jenis cahaya mana yang bayangannya selalu searah dan tidak terpengaruh jarak?</li><li>Parameter apa yang mengatur sudut dan kelembutan tepi sorotan Spot light?</li><li>Apa fungsi <em>World Environment</em> (node Background) pada scene kota?</li><li>Bagaimana material emisif membuat suasana malam terlihat hidup?</li><li>Ketika matahari rendah (senja), apa yang terjadi pada arah dan panjang bayangan?</li></ol><details><summary>Kunci jawaban</summary><ol><li>Directional light (SUN).</li><li><code>spot_size</code> (sudut kerucut) dan <code>spot_blend</code> (kelembutan tepi).</li><li>Menjadi langit/latar scene — warna &amp; kekuatannya menentukan atmosfer terang/gelap keseluruhan.</li><li>Permukaan memancarkan cahaya sendiri (emission) — jendela gedung, lampu PJU tampak menyala tanpa perlu sumber cahaya tambahan di tiap titik.</li><li>Bayangan memanjang dan searah menjauhi matahari; suasana berubah hangat/gelap.</li></ol></details></details><h2 id="level-4-·-modul-4-—-kamera-virtual-animasi-ekspor" tabindex="-1">Level 4 · Modul 4 — Kamera Virtual, Animasi &amp; Ekspor <a class="header-anchor" href="#level-4-·-modul-4-—-kamera-virtual-animasi-ekspor" aria-label="Permalink to &quot;Level 4 · Modul 4 — Kamera Virtual, Animasi &amp; Ekspor&quot;">​</a></h2><p><strong>±7–8 jam</strong> · prasyarat: lulus Level 3.</p><p>Puncak perjalanan: empat kamera virtual (drone orbit, street eye-level ber-DOF, isometric ortho, dashcam mobil), animasi keyframe 240 frame @ 24 fps, siklus siang→senja→malam yang di-<em>bake</em>, lalu produksi akhir: video MP4 H.264 dan Web 3D <code>.glb</code>.</p><p><img src="'+n+'" alt="Drone orbit di atas kota pada frame 200 (malam) — Level 4"></p><p><strong>Kompetensi:</strong></p><ul><li>Membedakan proyeksi perspektif vs ortografik, mengatur lensa &amp; depth of field</li><li>Memasang path curve + constraint <code>FOLLOW_PATH</code> &amp; <code>TRACK_TO</code> (drone orbit)</li><li>Membaca &amp; membuat keyframe: BEZIER (lift) vs LINEAR (mobil + roda berputar = jarak/radius)</li><li>Men-<em>bake</em> siklus siang-malam (energi SUN, World Background, PJU) di sepanjang timeline</li><li>Render animasi ke MP4 H.264 dan ekspor <code>.glb</code> untuk web viewer</li></ul><p><strong>Belajar di:</strong> <a href="/modul/modul-04.html#i-2-konsep-dasar-1-frame-fps-dan-timeline-untuk-pemula">Konsep Frame, FPS &amp; Timeline</a> → <a href="/modul/modul-04.html#iii-1-task-i-mengenal-4-kamera-virtual">Task I–V</a> → <a href="/modul/modul-04.html#lampiran-b-cookbook-resep-cepat">Cookbook</a>.</p><p><strong>Gerbang kelulusan — ceklis portofolio <code>prak4_[NIM]</code>:</strong></p><ul><li>[ ] <code>prak4_[NIM].blend</code>: scene + rig kamera + seluruh animasi utuh</li><li>[ ] <code>CityTour.mp4</code>: render 240 frame dari kamera selain drone default (ganti kamera aktif dulu)</li><li>[ ] Tangkapan 4 kamera virtual + 1 pasangan bukti animasi (lift atau mobil)</li><li>[ ] <code>.glb</code> + tangkapan tampilannya di web viewer</li><li>[ ] Laporan singkat: tabel keyframe terisi + penjelasan BEZIER vs LINEAR</li></ul><details><summary><b>Uji penempatan Level 4</b></summary><ol><li>Video 240 frame pada 24 fps berdurasi berapa detik?</li><li>Apa beda interpolasi BEZIER dan LINEAR pada keyframe?</li><li>Dua constraint apa yang membuat kamera drone mengorbit sambil terus menghadap target?</li><li>Kamera isometric memakai jenis proyeksi apa dan apa ciri hasilya?</li><li>Untuk apa format <code>.glb</code> diekspor — dan kenapa bukan <code>.mp4</code>?</li></ol><details><summary>Kunci jawaban</summary><ol><li>10 detik (240 ÷ 24).</li><li>BEZIER = pelan-cepat-pelan (halus, cocok lift); LINEAR = kecepatan konstan (cocok mobil &amp; putaran roda).</li><li><code>FOLLOW_PATH</code> (ikut kurva orbit) + <code>TRACK_TO</code> (menghadap target).</li><li>Ortografik — tidak ada perspektif menjauh; ukuran objek tetap walau jauh.</li><li><code>.glb</code> = model 3D interaktif untuk web (viewer bisa diputar/zoom); <code>.mp4</code> = video flat yang tak bisa diinteraksi.</li></ol></details></details><h2 id="capstone-—-city-tour-kampus-sendiri-wajib" tabindex="-1">Capstone — City Tour Kampus Sendiri (Wajib) <a class="header-anchor" href="#capstone-—-city-tour-kampus-sendiri-wajib" aria-label="Permalink to &quot;Capstone — City Tour Kampus Sendiri (Wajib)&quot;">​</a></h2><p>Capstone <strong>wajib</strong> dan menjadi syarat penuntasan workshop: rancang denah &amp; masterplan kawasan kampus versimu sendiri (pola Level 1 &amp; 3), bangun kawasannya dengan pencahayaan pilihanmu, lalu produksi video city tour MP4 + Web 3D <code>.glb</code> (pola Level 4).</p><p>Seluruh panduan langkah demi langkah, artefak wajib, dan rubrik penilaian ada di halaman khusus: <strong><a href="/capstone.html">Capstone: City Tour Kampus Sendiri →</a></strong></p><h2 id="pertanyaan-umum" tabindex="-1">Pertanyaan Umum <a class="header-anchor" href="#pertanyaan-umum" aria-label="Permalink to &quot;Pertanyaan Umum&quot;">​</a></h2><p><strong>Kapan bisa mulai? Kapan saja</strong> — workshop self-paced tanpa jadwal. Rekomendasi: mulai ±5 minggu sebelum semester praktikum Komputer Grafik, agar capstone selesai tepat waktu.</p><p><strong>Saya belum pernah membuka Blender sama sekali.</strong> Justru ini tempatnya mulai. Level 1 ditulis untuk pemula nol besar: semua konsep dijelaskan sebelum dipakai, dan tiap modul punya Lampiran A Glossarium + Lampiran B Cookbook resep cepat.</p><p><strong>Kalau saya macet / hasil berbeda dari dokumentasi?</strong> Cek <a href="/modul/modul-02.html#lampiran-b-cookbook-resep-cepat">Cookbook</a> modul yang sedang dikerjakan — kumpulan resep cepat untuk masalah paling sering. Masih mentok? Catat langkah terakhirmu — itu bahan diskusi bagus saat praktikum dimulai.</p><p><strong>Boleh melewati level?</strong> Boleh, lewat uji penempatan di tiap level (Level 1–2). Level 3–4 tetap ditempuh penuh karena capstone membutuhkan keduanya.</p><p><strong>Apa yang saya dapat setelah selesai?</strong> Portofolio 3D utuh: 4 file <code>.blend</code> + video MP4 + model Web 3D karya sendiri — diverifikasi dosen pengampu saat praktikum Komputer Grafik dimulai, dan menjadi bekal nilai praktikum.</p>',62)])])}const j=t(d,[["render",s]]);export{y as __pageData,j as default};
